SELECT (DATE_TRUNC('DAY', "SCHEDULED_AT")) AS "TIME_BUCKET", SUM(CASE WHEN STATE = 'FAILED' AND TASK_NAME = GRAPH_ROOT_TASK_ID THEN 1 ELSE 0 END) AS "PIPE_ROOT_FAILURES" FROM (SELECT "NAME" AS TASK_NAME, "DATABASE_NAME" AS DATABASE_NAME, "SCHEMA_NAME" AS SCHEMA_NAME, "STATE" AS STATE, "ERROR_CODE" AS ERROR_CODE, "QUERY_ID" AS QUERY_ID, "GRAPH_ROOT_TASK_ID" AS GRAPH_ROOT_TASK_ID, "GRAPH_RUN_GROUP_ID" AS GRAPH_RUN_GROUP_ID, "RUN_ID" AS RUN_ID, (TRY_TO_TIMESTAMP_NTZ("SCHEDULED_TIME")) AS SCHEDULED_AT, (TRY_TO_TIMESTAMP_NTZ("QUERY_START_TIME")) AS STARTED_AT, (TRY_TO_TIMESTAMP_NTZ("COMPLETED_TIME")) AS COMPLETED_AT, (DATEDIFF(SECOND, (TRY_TO_TIMESTAMP_NTZ("SCHEDULED_TIME")), (TRY_TO_TIMESTAMP_NTZ("COMPLETED_TIME")))) AS DURATION_SEC, PERCENT_RANK() OVER (PARTITION BY "NAME" ORDER BY (DATEDIFF(SECOND, (TRY_TO_TIMESTAMP_NTZ("SCHEDULED_TIME")), (TRY_TO_TIMESTAMP_NTZ("COMPLETED_TIME"))))) AS DURATION_PERCENT_RANK, SUM(CASE WHEN "STATE" = 'FAILED' THEN 1 ELSE 0 END) OVER (PARTITION BY "NAME") AS TASK_FAILURE_COUNT, MAX(CASE WHEN "STATE" = 'SUCCEEDED' THEN (TRY_TO_TIMESTAMP_NTZ("COMPLETED_TIME")) END) OVER (PARTITION BY "NAME") AS LAST_SUCCESS_AT, MAX((TRY_TO_TIMESTAMP_NTZ("SCHEDULED_TIME"))) OVER () AS OBSERVED_THROUGH_AT, (DATEDIFF(SECOND, MAX(CASE WHEN "STATE" = 'SUCCEEDED' THEN (TRY_TO_TIMESTAMP_NTZ("COMPLETED_TIME")) END) OVER (PARTITION BY "NAME"), MAX((TRY_TO_TIMESTAMP_NTZ("SCHEDULED_TIME"))) OVER ())) AS SECONDS_SINCE_LAST_SUCCESS FROM task_history) AS base GROUP BY (DATE_TRUNC('DAY', "SCHEDULED_AT")) ORDER BY "PIPE_ROOT_FAILURES" DESC NULLS LAST, "TIME_BUCKET" LIMIT 100
